```r
vec <- c(2, 3, 5, 6, 7, 8, 16, 19, 22, 23, 24)

# Using run to identify start and end of continuous sequences
runs <- unlist(strsplit(as.character(vec), split = " "))
starts <- c()
ends <- c()

for (i in 1:length(runs)) {
  if (runs[i] == " ") {
    if (length(starts) == 0) {
      starts <- c(runs[i])
    } else {
      starts <- c(starts, runs[i])
    }
